        public static MarkupString SVGConColor(string svg, string color)
        {
            string id = "svgColor_" + Guid.NewGuid().ToString("N");

            svg = svg.Replace("id=\"svg1\"", $"id=\"{id}\"");

            string style =
                $"<style>#{id} path {{ " +
                $"fill: {color} !important; " +
                $"fill-opacity: 1 !important; " +
                $"stroke: #000000 !important; " +
                $"stroke-opacity: 1 !important; " +
                $"}}</style>";

            svg = svg.Replace("</svg>", style + "</svg>");

            return new MarkupString(svg);
        }
